statement-break-example:
mientras ($count < 10) {
    if ($count == 5) {
        echo "Stopping at 5"
        break
    }
    $count de eco
    $count = $count + 1
}

statement-continue-example:
para $item en [["apple","skip","cherry"]] {
    if ($item == "skip") {
        continue
    }
    $item de eco
}

statement-exec-example:
$script = {path: "myscript.csh", name: "My Script"}
exec $script.path arg1 arg2

para $file en (dir "*.csh") {
    exec $file.path
}
